from decimal import Decimal, InvalidOperation, ROUND_DOWN


def encode_amount(dollars: str) -> str:
    s = dollars.strip()

    if s.startswith("$"):
        s = s[1:].strip()

    sign = "+"
    if s.startswith(("+", "-")):
        sign = s[0]
        s = s[1:].strip()
        if s.startswith("$"):
            s = s[1:].strip()

    try:
        value = Decimal(s)
    except (InvalidOperation, ValueError):
        raise ValueError("invalid dollar amount")

    if value < 0:
        sign = "-"
        value = -value

    cents_decimal = value * 100
    if cents_decimal != cents_decimal.to_integral_value(rounding=ROUND_DOWN):
        raise ValueError("amount has more than two decimal places")

    cents = int(cents_decimal)
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

