def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        num_str = dollars[1:]
    else:
        sign = '+'
        num_str = dollars

    # Split into dollars and cents
    if '.' in num_str:
        dollars_part, cents_part = num_str.split('.', 1)
    else:
        dollars_part = num_str
        cents_part = ''

    # Pad cents to exactly 2 digits
    if len(cents_part) == 0:
        cents_part = '00'
    elif len(cents_part) == 1:
        cents_part = cents_part + '0'
    elif len(cents_part) > 2:
        cents_part = cents_part[:2]

    # Remove leading zeros from dollars_part unless the whole number is zero
    dollars_part = dollars_part.lstrip('0')
    if dollars_part == '':
        dollars_part = '0'

    # Combine into minor units (cents)
    if dollars_part == '0' and cents_part == '00':
        digits = '0'
    else:
        digits = dollars_part + cents_part
        # Remove any leading zeros (e.g., "00" -> "0")
        digits = digits.lstrip('0')
        if digits == '':
            digits = '0'

    # Compute Luhn-style check digit: sum of digits mod 10
    digit_sum = sum(int(d) for d in digits)
    check = digit_sum % 10

    return f"{sign}{digits}#{check}"

