from decimal import Decimal, InvalidOperation


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar-denominated decimal string as integer cents in the ledger
    wire format.

    Examples:
        "12.30" -> "1230"
        "-0.07" -> "-7"
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    cents = value * 100
    if cents != cents.to_integral_value():
        raise ValueError("amount has more than two decimal places")

    cents_int = int(cents)
    return str(cents_int)

