import ledger


def record(acct, cents, note):
    return ledger.post(acct, cents, memo=note)

def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string (e.g. '12.30', '-0.07') to wire format.
    Returns <sign_byte><integer_cents as 4 bytes big-endian>.
    """
    try:
        val = float(dollars)
    except ValueError:
        raise ValueError("malformed amount")

    sign_byte = 0x01 if val >= 0 else 0x00
    cents = round(val * 100)
    if cents < -2147483648 or cents > 2147483647:
        raise ValueError("amount out of range")
    unsigned_cents = cents & 0xFFFFFFFF
    return bytes([sign_byte]) + unsigned_cents.to_bytes(4, 'big', signed=False)

