def encode_amount(dollars: str) -> str:
    # Parse sign
    if dollars.startswith('-'):
        sign = '-'
        rest = dollars[1:]
    else:
        sign = '+'
        rest = dollars

    # Split dollars and cents
    if '.' in rest:
        dollars_part, cents_part = rest.split('.', 1)
    else:
        dollars_part = rest
        cents_part = '00'

    # Pad cents to exactly 2 digits
    if len(cents_part) == 1:
        cents_part = cents_part + '0'
    elif len(cents_part) == 0:
        cents_part = '00'
    elif len(cents_part) > 2:
        # Truncate or handle error? Spec implies proper input; we take first two digits.
        cents_part = cents_part[:2]

    # Remove possible leading zeros in dollars_part but keep one zero if empty
    if dollars_part == '' or dollars_part == '0':
        dollars_part = '0'
    else:
        dollars_part = dollars_part.lstrip('0')
        if dollars_part == '':
            dollars_part = '0'

    # Combine into minor units string
    if dollars_part == '0':
        # Avoid something like "00" + "07" -> "007", we want "7"
        minor_str = str(int(cents_part))
    else:
        minor_str = dollars_part + cents_part

    # Calculate check digit
    digit_sum = sum(int(ch) for ch in minor_str)
    check = digit_sum % 10

    return f"{sign}{minor_str}#{check}"

