def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        num_str = dollars[1:]
    else:
        sign = '+'
        num_str = dollars

    # Split into dollars and cents
    if '.' in num_str:
        parts = num_str.split('.')
        dollars_part = parts[0]
        cents_part = parts[1]
        if len(cents_part) == 1:
            cents_part += '0'
        elif len(cents_part) == 0:
            cents_part = '00'
        elif len(cents_part) > 2:
            raise ValueError("too many decimal places")
    else:
        dollars_part = num_str
        cents_part = '00'

    # Validate numeric characters
    if not dollars_part.isdigit() and dollars_part != '':
        raise ValueError("invalid dollars part")
    if not cents_part.isdigit():
        raise ValueError("invalid cents part")
    if dollars_part == '':
        dollars_part = '0'

    # Compute minor units (cents) as integer string without leading zeros (except zero itself)
    total_cents = int(dollars_part + cents_part)
    digits = str(total_cents)

    # Compute check digit
    digit_sum = sum(int(d) for d in digits)
    check = digit_sum % 10

    return f"{sign}{digits}#{check}"

