def encode_amount(dollars: str) -> str:
    # Format: <sign_char><space-padded integer_cents>
    # sign_char: 'C' for credit (>=0), 'D' for debit (<0)
    dollars = dollars.strip()
    if not dollars:
        raise ValueError("Empty amount string")

    # Determine sign
    negative = dollars.startswith('-')
    if negative:
        num_str = dollars[1:]
        sign_char = 'D'
    else:
        num_str = dollars
        sign_char = 'C'

    # Parse dollars and cents
    if '.' not in num_str:
        dollars_part = num_str
        cents_part = '00'
    else:
        parts = num_str.split('.')
        if len(parts) != 2:
            raise ValueError("Malformed amount string")
        dollars_part, cents_part = parts
        if not cents_part:
            cents_part = '00'
        elif len(cents_part) == 1:
            cents_part += '0'
        elif len(cents_part) > 2:
            raise ValueError("Too many decimal places")

    # Remove leading zeros from dollars part for cents calculation
    dollars_part = dollars_part.lstrip('0') or '0'

    # Convert to integer cents
    try:
        total_cents = int(dollars_part) * 100 + int(cents_part)
    except ValueError:
        raise ValueError("Non-numeric amount")

    # Format as 12-character space-padded string
    cents_str = str(total_cents)
    padded = cents_str.rjust(12)

    return sign_char + padded

