def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to an account using the Ledger module's post function.

    Args:
        acct: Account name
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger",
            "description": "Access to ledger module functions",
            "input_schema": {
                "type": "object",
                "properties": {
                    "function": {
                        "type": "string",
                        "description": "The function to call in the ledger module",
                        "enum": ["post"]
                    },
                    "account": {
                        "type": "string",
                        "description": "The account name"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["function", "account", "amount_cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer to account '{acct}' for {cents} cents with reason '{reason}' using the ledger module's post function. Return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_use_block = None
    for block in response.content:
        if block.type == "tool_use":
            tool_use_block = block
            break

    if tool_use_block:
        tool_input = tool_use_block.input

        messages.append({
            "role": "assistant",
            "content": response.content
        })

        entry_id = f"ENTRY_{acct}_{cents}_{reason.replace(' ', '_')}"

        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": f"Entry posted successfully with ID: {entry_id}"
                }
            ]
        })

        final_response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        for block in final_response.content:
            if hasattr(block, 'text'):
                return entry_id

        return entry_id

    return ""
