def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s or s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole_part, frac_part = s.split(".", 1)
    else:
        whole_part, frac_part = s, ""

    if whole_part == "" and frac_part == "":
        raise ValueError("invalid amount")

    if whole_part == "":
        whole_part = "0"

    if not whole_part.isdigit() or (frac_part and not frac_part.isdigit()):
        raise ValueError("invalid amount")

    if len(frac_part) > 2:
        if any(ch != "0" for ch in frac_part[2:]):
            raise ValueError("amount has more than two decimal places")
        frac_part = frac_part[:2]

    frac_part = frac_part.ljust(2, "0")

    cents = int(whole_part) * 100 + int(frac_part)
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10
    sign = "-" if negative else "+"

    return f"{sign}{digits}#{check}"

