import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo.
    Returns the entry id.

    Uses Claude to call the ledger module's post function.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The reason or memo for the transaction"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to get the tool use
    for block in response.content:
        if block.type == "tool_use":
            if block.name == "post":
                # Simulate calling the ledger module's post function
                # In a real scenario, this would call the actual ledger module
                entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
                return entry_id

    return ""
