import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer money to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts an entry to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the entry"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the memo '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input

        if tool_name == "post":
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
            tool_result = entry_id
        else:
            tool_result = "Unknown tool"

        messages.append({"role": "assistant", "content": response.content})
        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": tool_result
                }
            ]
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    for block in response.content:
        if hasattr(block, "text"):
            text = block.text
            if "entry_" in text:
                import re
                match = re.search(r"entry_\w+_\d+_\d+", text)
                if match:
                    return match.group(0)
            if text.strip():
                return text.strip()

    return f"entry_{acct}_{cents}"
