import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.
    Uses Claude to call the ledger module's post function.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The transaction memo/reason"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason '{reason}'. Use the post tool and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use":
                if block.name == "post":
                    tool_input = block.input
                    entry_id = f"entry_{acct}_{tool_input.get('amount', cents)}"
                    return entry_id

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if "entry" in text.lower():
                import re
                match = re.search(r'entry[_\s]?(\w+)', text, re.IGNORECASE)
                if match:
                    return match.group(0)

    return f"entry_{acct}_{cents}"


if __name__ == "__main__":
    entry_id = transfer("checking", 10000, "Monthly salary")
    print(f"Entry ID: {entry_id}")
