# solution.py
def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format."""
    if not isinstance(dollars, str):
        raise ValueError("Input must be a string")

    stripped = dollars.strip()
    if not stripped:
        raise ValueError("Empty amount string")

    # Determine sign
    sign = "+"
    if stripped.startswith("-"):
        sign = "-"
        numeric_part = stripped[1:]
    else:
        numeric_part = stripped

    if not numeric_part:
        raise ValueError("Malformed amount: sign without digits")

    # Split into integer and fractional parts
    if "." in numeric_part:
        integer_str, frac_str = numeric_part.split(".", 1)
    else:
        integer_str = numeric_part
        frac_str = ""

    if not integer_str and not frac_str:
        raise ValueError("Malformed amount")

    # Validate digits
    for ch in integer_str + frac_str:
        if not ch.isdigit():
            raise ValueError(f"Non-digit character in amount: {ch!r}")

    # Strip leading zeros from integer part
    integer_str = integer_str.lstrip("0") or "0"

    # Pad or truncate fractional part to exactly 2 digits
    if len(frac_str) < 2:
        frac_str = frac_str.ljust(2, "0")
    elif len(frac_str) > 2:
        frac_str = frac_str[:2]

    # Remove trailing zeros from fractional part
    # Keep at least one fractional digit if integer is "0"
    # Actually, wire format requires compactness — remove trailing zeros, keep minimal representation
    frac_str = frac_str.rstrip("0")

    # Build result
    if frac_str:
        result = f"{integer_str}.{frac_str}"
    else:
        result = integer_str

    if result == "0":
        # Zero has no sign in wire format
        return "0"

    return f"{sign}{result}"

