import anthropic
import json

client = anthropic.Anthropic()


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo.
    Returns the entry id.
    """

    tools = [
        {
            "name": "post",
            "description": "Post a ledger entry with an account, amount in cents, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with memo '{reason}' using the ledger post function."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if not tool_use_block:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input

        if tool_name == "post":
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
            tool_result = {
                "entry_id": entry_id,
                "status": "success",
                "account": tool_input.get("account"),
                "cents": tool_input.get("cents"),
                "memo": tool_input.get("memo")
            }
        else:
            tool_result = {"error": f"Unknown tool: {tool_name}"}

        messages.append({
            "role": "assistant",
            "content": response.content
        })

        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": json.dumps(tool_result)
                }
            ]
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if "entry_" in text:
                for word in text.split():
                    if word.startswith("entry_"):
                        return word

    return f"entry_{acct}_{cents}_{hash(reason) % 10000}"
