def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]

    if '.' in s:
        whole, frac = s.split('.', 1)
    else:
        whole, frac = s, ''

    if whole == '':
        whole = '0'

    frac = (frac + '00')[:2]

