def encode_amount(dollars: str) -> str:
    # Normalize sign: strip a leading '+' if present, keep '-' if present
    sign = ""
    s = dollars.strip()
    if s.startswith("+"):
        s = s[1:]
    elif s.startswith("-"):
        sign = "-"
        s = s[1:]

    if "." in s:
        int_part, frac_part = s.split(".", 1)
    else:
        int_part, frac_part = s, ""

    # frac_part must be exactly 2 digits; pad or truncate? spec says "money amount e.g. '12.30', '-0.07'"
    # assume exactly two decimal places in input and we preserve them; pad if needed
    if len(frac_part) < 2:
        frac_part = frac_part.ljust(2, "0")
    elif len(frac_part) > 2:
        frac_part = frac_part[:2]

    # Remove leading zeros from integer part, keep at least one digit
    int_part = int_part.lstrip("0") or "0"

    amount = f"{int_part}.{frac_part}"
    if sign == "-" and amount == "0.00":
        sign = ""  # normalize negative zero to positive zero
    return f"{sign}{amount}"

