import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using Claude with tool use.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "reason": {
                        "type": "string",
                        "description": "Memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        tool_use = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use and tool_use.name == "post":
            tool_input = tool_use.input
            entry_id = f"entry_{tool_use.id}"
            return entry_id

    return ""
