import anthropic
import json
from ledger import post, PostError

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

tools = [
    {
        "name": "transfer",
        "description": "Posts a transfer to an account with a specified amount and reason",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account to post the transfer to"
                },
                "cents": {
                    "type": "number",
                    "description": "The amount in cents to transfer"
                },
                "reason": {
                    "type": "string",
                    "description": "The reason or memo for the transfer"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }
]

def transfer(acct: str, cents, reason: str) -> int:
    """
    Posts a transfer to an account using the ledger API.

    Args:
        acct: The account to post to
        cents: The amount in cents
        reason: The reason/memo for the transfer

    Returns:
        The entry id of the posted transfer

    Raises:
        PostError: If the post fails (unknown account, malformed amount, etc.)
    """
    return post(acct, cents, memo=reason)


def process_tool_call(tool_name: str, tool_input: dict):
    """Process a tool call and return the result"""
    if tool_name == "transfer":
        try:
            entry_id = transfer(
                acct=tool_input["acct"],
                cents=tool_input["cents"],
                reason=tool_input["reason"]
            )
            return {"success": True, "entry_id": entry_id}
        except PostError as e:
            return {"success": False, "error": str(e)}
    return {"success": False, "error": f"Unknown tool: {tool_name}"}


def run_transfer_agent(request: str) -> dict:
    """
    Run an agentic loop to process transfer requests using Claude.

    Args:
        request: A natural language request to process a transfer

    Returns:
        The result of the transfer operation
    """
    messages = [
        {"role": "user", "content": request}
    ]

    while True:
        response = client.messages.create(
            model=MODEL_NAME,
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "end_turn":
            return {"status": "completed", "message": "Transfer processed"}

        if response.stop_reason == "tool_use":
            tool_results = []
            for block in response.content:
                if block.type == "tool_use":
                    tool_result = process_tool_call(block.name, block.input)
                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": block.id,
                        "content": json.dumps(tool_result)
                    })

            messages.append({"role": "assistant", "content": response.content})
            messages.append({"role": "user", "content": tool_results})
        else:
            break

    return {"status": "unknown", "message": "Unexpected stop reason"}


if __name__ == "__main__":
    result = run_transfer_agent("Please transfer 5000 cents to account 'savings' with the reason 'monthly deposit'")
    print(json.dumps(result, indent=2))
