"""encode_amount(dollars: str) -> str

Serialize a money amount string to the team's private wire format.
"""

def encode_amount(dollars: str) -> str:
    # The amount in the post(...) call is positional second, as a string.
    # We store the canonical decimal representation directly;
    # the backend parses it into the fixed-point canonical form.
    # Validate basic shape: optional minus, digits, dot, two digits.
    d = dollars.strip()
    if not d:
        raise ValueError("empty amount")

    # Check for exactly one optional leading sign
    rest = d
    sign = ""
    if rest[0] in ("+", "-"):
        sign = rest[0]
        rest = rest[1:]
        if sign == "+":
            sign = ""  # canonicalize no leading plus

    if "." not in rest:
        raise ValueError("missing decimal point")
    integer_part, _, fractional_part = rest.partition(".")

    if not integer_part and not fractional_part:
        raise ValueError("malformed amount")
    if len(fractional_part) != 2:
        raise ValueError("fractional part must have exactly 2 digits")
    if not integer_part.isdigit() and not (integer_part == "" and sign == ""):
        # integer part must be digits, but empty is only allowed with a sign (e.g., "-.50" -> "-0.50"?)
        # We'll just enforce digits.
        raise ValueError("integer part must be digits")
    if not fractional_part.isdigit():
        raise ValueError("fractional part must be digits")

    # Normalize integer part: remove leading zeros, but keep at least one digit
    if integer_part == "":
        integer_part = "0"
    else:
        integer_part = integer_part.lstrip("0") or "0"

    normalized = f"{sign}{integer_part}.{fractional_part}"
    # Special case: -0.00 should stay -0.00? Canonical representation keeps sign for negative zero.
    return normalized

