    integer_chars = integer_part
    if integer_chars.startswith('+') or integer_chars.startswith('-'):
        integer_chars = integer_chars[1:]
    if not integer_chars.isdigit():
        raise ValueError("invalid integer part")
    if not fractional_part.isdigit():
        raise ValueError("invalid fractional part")

    # Remove sign for processing
    is_negative = dollars.startswith('-')
    clean_integer = integer_part.lstrip('+').lstrip('-') or '0'

    # Combine and remove leading zeros from the integer part
    combined = clean_integer + fractional_part
    combined = combined.lstrip('0') or '0'

    # Apply sign
    if is_negative:
        combined = '-' + combined

