def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string (e.g. '12.30', '-0.07') to the team's private wire format.
    """
    # Validate and parse the input
    try:
        value = float(dollars)
    except ValueError:
        raise ValueError(f"Invalid amount format: {dollars}")

    # Check for exactly two decimal places
    if '.' in dollars:
        parts = dollars.split('.')
        if len(parts) != 2 or len(parts[1]) != 2:
            raise ValueError(f"Amount must have exactly two decimal places: {dollars}")
    else:
        raise ValueError(f"Amount must include decimal point and two decimal places: {dollars}")

    # Convert to integer cents
    cents = int(round(value * 100))

    # Wire format: 8-byte big-endian signed integer
    return cents.to_bytes(8, byteorder='big', signed=True).hex()

def encode_amount(dollars: str) -> str:
    s = dollars.strip()

    if s.startswith("-"):
        sign = "-"
        num = s[1:]
    else:
        sign = "+"
        num = s[1:] if s.startswith("+") else s

    if "." in num:
        d_part, c_part = num.split(".")
        if not d_part:
            d_part = "0"
        c_part = (c_part + "00")[:2]
    else:
        d_part = num if num else "0"
        c_part = "00"

    minor = int(d_part + c_part)
    digits = str(minor)
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

