import anthropic
import json
import re

client = anthropic.Anthropic()
ledger_entries = {}
next_entry_id = 1

def post(acct: str, cents: int, reason: str) -> int:
    """Post an entry to a ledger account."""
    global next_entry_id

    entry = {
        "id": next_entry_id,
        "account": acct,
        "amount": cents,
        "memo": reason
    }
    ledger_entries[next_entry_id] = entry
    result_id = next_entry_id
    next_entry_id += 1

    return result_id

def transfer(acct: str, cents: int, reason: str) -> int:
    """Transfer cents to account using reason as memo and return entry id."""
    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=[
            {
                "name": "ledger_post",
                "description": "Post an entry to the ledger using the ledger module's post function",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "acct": {
                            "type": "string",
                            "description": "The account to post to"
                        },
                        "cents": {
                            "type": "integer",
                            "description": "The amount in cents to post"
                        },
                        "reason": {
                            "type": "string",
                            "description": "The memo or reason for the transaction"
                        }
                    },
                    "required": ["acct", "cents", "reason"]
                }
            }
        ],
        messages=[
            {
                "role": "user",
                "content": f"Please post a transfer of {cents} cents to account '{acct}' with the reason '{reason}'. Use the ledger_post tool to do this."
            }
        ]
    )

    entry_id = None
    for content_block in message.content:
        if content_block.type == "tool_use":
            if content_block.name == "ledger_post":
                tool_input = content_block.input
                entry_id = post(
                    acct=tool_input["acct"],
                    cents=tool_input["cents"],
                    reason=tool_input["reason"]
                )

    if entry_id is None:
        entry_id = post(acct, cents, reason)

    return entry_id

