def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string into the internal wire format.
    Negative values are prefixed with '-', followed by the integer
    representation of cents without any decimal point.
    """
    negative = dollars.startswith('-')
    value = dollars[1:] if negative else dollars

    if '.' not in value:
        cents = int(value) * 100
    else:
        integer_part, fractional_part = value.split('.')
        if len(fractional_part) == 0:
            frac = 0
        elif len(fractional_part) == 1:
            frac = int(fractional_part) * 10
        elif len(fractional_part) == 2:
            frac = int(fractional_part)
        else:
            frac = int(fractional_part[:2] + '.' + fractional_part[2:])
        cents = int(integer_part) * 100 + frac

    return f"-{cents}" if negative else str(cents)

