import anthropic
import json

def transfer(acct, cents, reason):
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.
    Uses Claude to interact with the ledger module's post function.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger. Posts cents to account acct using reason as the memo.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use":
                tool_name = block.name
                tool_input = block.input

                if tool_name == "post":
                    entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
                    return entry_id

    return None


if __name__ == "__main__":
