import anthropic
import json

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

# Define the tools for ledger operations
tools = [
    {
        "name": "ledger_post",
        "description": "Posts an entry to the ledger with a specified account, amount in cents, and memo",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

# Simulated ledger storage
ledger_entries = []
next_entry_id = 1

def ledger_post(account, cents, memo):
    """Post an entry to the ledger and return the entry id"""
    global next_entry_id
    entry_id = next_entry_id
    next_entry_id += 1

    entry = {
        "id": entry_id,
        "account": account,
        "cents": cents,
        "memo": memo
    }
    ledger_entries.append(entry)
    return entry_id

def process_tool_call(tool_name, tool_input):
    """Process tool calls and return results"""
    if tool_name == "ledger_post":
        entry_id = ledger_post(
            tool_input["account"],
            tool_input["cents"],
            tool_input["memo"]
        )
        return entry_id
    return None

def transfer(acct, cents, reason):
    """Transfer funds using Claude to post to the ledger"""

    user_message = f"Post {cents} cents to account {acct} with reason: {reason}"

    messages = [
        {"role": "user", "content": user_message}
    ]

    # Call Claude with tools
    response = client.messages.create(
        model=MODEL_NAME,
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    while response.stop_reason == "tool_use":
        tool_use = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if not tool_use:
            break

        tool_name = tool_use.name
        tool_input = tool_use.input

        # Execute the tool
        result = process_tool_call(tool_name, tool_input)

        # Add assistant response and tool result to messages
        messages.append({"role": "assistant", "content": response.content})
        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use.id,
                    "content": str(result)
                }
            ]
        })

        # Get next response
        response = client.messages.create(
            model=MODEL_NAME,
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    # Extract the entry id from the last tool result
    # Find the tool_result in the messages
    for msg in reversed(messages):
        if msg.get("role") == "user":
            content = msg.get("content", [])
            if isinstance(content, list):
                for item in content:
                    if item.get("type") == "tool_result":
                        try:
                            return int(item.get("content", ""))
                        except (ValueError, TypeError):
                            pass

    return None


if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("checking", 10000, "Monthly salary")
    print(f"Transfer posted with entry id: {entry_id}")

    # Verify the entry was posted
    if entry_id is not None:
        for entry in ledger_entries:
            if entry["id"] == entry_id:
                print(f"Verified entry: {entry}")
