# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the ledger tools
tools = [
    {
        "name": "ledger_post",
        "description": "Posts a transaction to the ledger",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "Account identifier"
                },
                "cents": {
                    "type": "integer",
                    "description": "Amount in cents"
                },
                "reason": {
                    "type": "string",
                    "description": "Memo or reason for the transaction"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }
]

# Simulated ledger storage
ledger_entries = []
entry_counter = 0

def ledger_post(acct, cents, reason):
    """Posts a transaction to the ledger and returns the entry id"""
    global entry_counter
    entry_counter += 1
    entry = {
        "id": entry_counter,
        "account": acct,
        "amount_cents": cents,
        "memo": reason
    }
    ledger_entries.append(entry)
    return entry_counter

def process_tool_call(tool_name, tool_input):
    """Process tool calls and return results"""
    if tool_name == "ledger_post":
        return ledger_post(
            tool_input["acct"],
            tool_input["cents"],
            tool_input["reason"]
        )
    return None

def transfer(acct, cents, reason):
    """
    Transfer funds using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo or reason for the transaction

    Returns:
        The entry id of the posted transaction
    """
    # Create a message asking Claude to post the transfer
    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer to account '{acct}' for {cents} cents with the reason '{reason}'. Use the ledger_post tool to do this."
        }
    ]

    # Call Claude with tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    while response.stop_reason == "tool_use":
        # Find the tool use block
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        # Execute the tool
        tool_result = process_tool_call(tool_use_block.name, tool_use_block.input)

        # Add the assistant's response and tool result to messages
        messages.append({"role": "assistant", "content": response.content})
        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": str(tool_result)
                }
            ]
        })

        # Continue the conversation
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    # Extract the result from Claude's final response
    for block in response.content:
        if hasattr(block, 'text'):
            # Look for a number in the response that represents the entry id
            text = block.text
            # Try to find the entry id in the response
