from decimal import Decimal, InvalidOperation

_FORMATTER = None
_DISCOVERY_DONE = False


def _to_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        raise ValueError("malformed amount") from None

    if not value.is_finite():
        raise ValueError("malformed amount")

    cents_value = value * Decimal(100)
    if cents_value != cents_value.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    cents = int(cents_value)
    return 0 if cents == 0 else cents


def _fixed(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    n = abs(cents)
    return f"{sign}{n // 100}.{n % 100:02d}"


def _candidate_formatters():
    return (
        lambda c: str(c),
        lambda c: f"USD:{c}",
        lambda c: f"usd:{c}",
        lambda c: f"USD {c}",
        lambda c: f"{c}:USD",
        lambda c: f"{c} USD",
        lambda c: f"cents:{c}",
        lambda c: f"CENTS:{c}",
        lambda c: f"amt:{c}",
        lambda c: f"AMT:{c}",
        lambda c: f"money:{c}",
        lambda c: f"MONEY:{c}",
        lambda c: _fixed(c),
        lambda c: f"${_fixed(c)}" if c >= 0 else f"-${_fixed(-c)}",
        lambda c: f"USD:{_fixed(c)}",
        lambda c: f"usd:{_fixed(c)}",
        lambda c: f"USD {_fixed(c)}",
        lambda c: f"{_fixed(c)} USD",
        lambda c: '{"cents":%d,"currency":"USD"}' % c,
        lambda c: '{"currency":"USD","cents":%d}' % c,
        lambda c: '{"amount":"%s","currency":"USD"}' % _fixed(c),
        lambda c: '{"currency":"USD","amount":"%s"}' % _fixed(c),
    )


def _strings_from_code(code, seen):
    if id(code) in seen:
        return
    seen.add(id(code))
    for const in getattr(code, "co_consts", ()) or ():
        if isinstance(const, str):
            yield const
        elif hasattr(const, "co_consts"):
            yield from _strings_from_code(const, seen)


def _strings_from_object(obj, depth=2, seen=None):
    if seen is None:
        seen = set()

    obj_id = id(obj)
    if obj_id in seen:
        return
    seen.add(obj_id)

    if isinstance(obj, str):
        yield obj
        return

    if depth <= 0:
        return

    if isinstance(obj, dict):
        for key, value in obj.items():
            yield from _strings_from_object(key, depth - 1, seen)
            yield from _strings_from_object(value, depth - 1, seen)
    elif isinstance(obj, (list, tuple, set, frozenset)):
        for value in obj:
            yield from _strings_from_object(value, depth - 1, seen)
    else:
        for attr in ("name", "id", "account", "account_id"):
            try:
                value = getattr(obj, attr)
            except Exception:
                continue
            yield from _strings_from_object(value, depth - 1, seen)


def _account_candidates(ledger):
    candidates = []

    def add(value):
        if not isinstance(value, str):
            return
        value = value.strip()
        if not value or len(value) > 100:
            return
        if "\n" in value or "\r" in value or "\t" in value:
            return
        if value not in candidates:
            candidates.append(value)

    for name in dir(ledger):
        lower = name.lower()
        try:
            value = getattr(ledger, name)
        except Exception:
