                    sig = inspect.signature(value)
                    required = [
                        p for p in sig.parameters.values()
                        if p.default is p.empty
                        and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
                    ]
                    if not required:
                        result = value()
                        for s in _strings_from_object(result, 3):
                            add(s)
                except Exception:
                    pass

        try:
            code = getattr(value, "__code__", None)
            if code is not None:
                for s in _strings_from_code(code, set()):
                    if "account" in s.lower() or ":" in s:
                        add(s)
        except Exception:
            pass

    for common in (
        "test",
        "default",
        "main",
        "cash",
        "bank",
        "checking",
        "savings",
        "ledger",
        "income",
        "expense",
        "expenses",
        "revenue",
        "assets:cash",
        "asset:cash",
        "equity:opening-balances",
