        try:
            helper = getattr(ledger, name)
        except Exception:
            continue

        if not callable(helper):
            continue

        try:
            result = helper(dollars)
        except Exception:
            continue

        if isinstance(result, str):
            return result
        if isinstance(result, bytes):
            try:
                return result.decode("ascii")
            except Exception:
                continue

    return None


