import re
from decimal import Decimal, InvalidOperation


_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        raise ValueError("malformed money amount")

    sign, whole, frac = match.groups()
    whole = whole or "0"
    frac = frac or ""
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if sign == "-" and cents:
        cents = -cents
    return cents


def _canonical_dollars(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _ledger_encoder_result(dollars: str, cents: int):
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "serialize_amount",
        "_serialize_amount",
        "format_amount",
        "_format_amount",
        "dollars_to_wire",
        "_dollars_to_wire",
        "money_to_wire",
        "_money_to_wire",
        "encode_money",
        "_encode_money",
    )

    candidates = (dollars, dollars.strip(), _canonical_dollars(cents), cents, Decimal(cents) / Decimal(100))

    for name in names:
        func = getattr(ledger, name, None)
        if not callable(func):
            continue

        for candidate in candidates:
            try:
                result = func(candidate)
            except Exception:
                continue
            if isinstance(result, str):
                return result

    return None


def encode_amount(dollars: str) -> str:
    cents = _parse_cents(dollars)

    discovered = _ledger_encoder_result(dollars, cents)
    if discovered is not None:
        return discovered

    return str(cents)

