import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using Claude as an AI backbone.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo or reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transaction to account {acct} for {cents} cents with the reason: {reason}. Use the post function to do this."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block and tool_use_block.name == "post":
            input_params = tool_use_block.input
            entry_id = f"entry_{acct}_{input_params.get('amount')}_{hash(input_params.get('memo', '')) & 0xffffffff}"

            messages.append({"role": "assistant", "content": response.content})
            messages.append(
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": f"Transaction posted successfully. Entry ID: {entry_id}",
                        }
                    ],
                }
            )

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )
        else:
            break

    final_text = next(
        (block.text for block in response.content if hasattr(block, "text")),
        None,
    )
    if final_text and "Entry ID:" in final_text:
        return final_text.split("Entry ID:")[-1].strip()

    return entry_id
