                        "type": "string",
                        "description": "The memo or reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the reason '{reason}' using the post function. Return just the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process tool use
    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block:
            # Simulate the ledger post function
            tool_input = tool_use_block.input
            entry_id = f"entry_{hash((tool_input['account'], tool_input['amount'], tool_input['memo'])) & 0xffffffff:08x}"

            # Add the assistant's response and tool result
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": entry_id
                    }
                ]
            })

            # Get the next response
            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    # Extract the entry id from the final response
    for block in response.content:
        if hasattr(block, 'text'):
            # Look for entry_id pattern in the response
            text = block.text
            if 'entry_' in text:
                # Extract the entry id
                import re
                match = re.search(r'entry_[a-f0-9]+', text)
                if match:
                    return match.group(0)
            # Also try to find it in plain text format
            lines = text.split('\n')
            for line in lines:
                if 'entry' in line.lower():
                    return line.strip()

    return entry_id
