def encode_amount(dollars: str) -> str:
    raw = dollars.strip()
    if raw.startswith("-"):
        sign = "-"
        num = raw[1:]
    elif raw.startswith("+"):
        sign = "+"
        num = raw[1:]
    else:
        sign = "+"
        num = raw

    if not num:
        num = "0"

    if "." in num:
        int_part, frac_part = num.split(".", 1)
        if not int_part:
            int_part = "0"
        frac_padded = (frac_part + "00")[:2]
        total_cents = int(int_part) * 100 + int(frac_padded)
    else:
        total_cents = int(num) * 100

    digits = str(total_cents)
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

