def encode_amount(dollars: str) -> str:
    raw = dollars.strip()
    if not raw:
        raise ValueError("Empty amount string")

    if raw[0] == '-':
        sign = '-'
        num_part = raw[1:]
    elif raw[0] == '+':
        sign = '+'
        num_part = raw[1:]
    else:
        sign = '+'
        num_part = raw

    try:
        value = Decimal(num_part)
    except InvalidOperation:
        raise ValueError(f"Invalid numeric amount: {dollars}")

    # Convert to minor units (integer cents)
    cents = int(value * 100)

    digits = str(abs(cents))
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

