import re

_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")


def _malformed_amount():
    try:
        import ledger

        exc_type = ledger.PostError
    except Exception:
        exc_type = ValueError

    try:
        raise exc_type("malformed amount")
    except TypeError:
        raise exc_type()


def encode_amount(dollars: str) -> str:
    match = _AMOUNT_RE.match(dollars) if isinstance(dollars, str) else None
    if match is None:
        _malformed_amount()

    sign, whole, frac_a, frac_b = match.groups()
    whole = whole or "0"
    frac = frac_a if frac_a is not None else frac_b
    frac = (frac or "").ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if sign == "-" and cents:
        cents = -cents

    return str(cents)

