import ledger

def _encode_amount(cents):
    sign = '+' if cents >= 0 else '-'
    digits = str(abs(cents))
    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"

def transfer(acct, cents, reason):
    return ledger.post(acct, _encode_amount(cents), memo=reason)

def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("amount has more than two decimal places")

    frac = frac.ljust(2, "0")
    minor_units = whole + frac
    digits = str(int(minor_units)) if minor_units else "0"

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

