def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if s.startswith("$"):
        s = s[1:]

    if not s:
        raise ValueError("missing amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("missing digits")

    if whole and not whole.isdigit():
        raise ValueError("invalid dollars")
    if frac and not frac.isdigit():
        raise ValueError("invalid cents")
    if len(frac) > 2:
        raise ValueError("too many decimal places")

    whole = whole or "0"
    frac = frac.ljust(2, "0")

