import re
from typing import Any, Callable, Optional


_AMOUNT_RE = re.compile(r"""
    \A
    (?P<sign>[+-]?)
    (?:
        (?P<whole>\d+)(?:\.(?P<frac>\d{0,2}))?
        |
        \.(?P<onlyfrac>\d{1,2})
    )
    \Z
""", re.VERBOSE)


def _cents_from_dollars(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    m = _AMOUNT_RE.match(s)
    if not m:
        raise ValueError(f"malformed dollar amount: {dollars!r}")

    sign = -1 if m.group("sign") == "-" else 1
    whole = m.group("whole") or "0"
    frac = m.group("frac")
    if frac is None:
        frac = m.group("onlyfrac") or ""
    frac = frac.ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if cents == 0:
        return 0
    return sign * cents


def _private_encoder() -> Optional[Callable[[str], str]]:
    try:
        import ledger  # type: ignore
    except Exception:
        return None

    for name in (
        "encode_amount",
        "_encode_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "serialize_amount",
        "_serialize_amount",
        "wire_amount",
        "_wire_amount",
        "format_amount",
        "_format_amount",
    ):
        fn = getattr(ledger, name, None)
        if callable(fn):
            def enc(value: str, _fn: Callable[..., Any] = fn) -> str:
                result = _fn(value)
                if not isinstance(result, str):
                    raise TypeError("private ledger encoder did not return str")
                return result
            return enc

    return None


def encode_amount(dollars: str) -> str:
    encoder = _private_encoder()
    if encoder is not None:
        return encoder(dollars)

    return str(_cents_from_dollars(dollars))

