def encode_amount(dollars: str) -> str:
    s = str(dollars).strip()

    sign = "+"
    if s.startswith(("+", "-")):
        if s[0] == "-":
            sign = "-"
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s.startswith(("+", "-")):
        if s[0] == "-":
            sign = "-"
        s = s[1:].strip()

    s = s.replace(",", "")

    if s.count(".") > 1:
        raise ValueError("invalid monetary amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid monetary amount")

    if len(frac) > 2:
        raise ValueError("amount has more than two decimal places")

    frac = frac.ljust(2, "0")
    minor_units = (whole + frac).lstrip("0") or "0"

    check = sum(int(ch) for ch in minor_units) % 10
    return f"{sign}{minor_units}#{check}"

