from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar amount as signed integer cents.

    Examples:
        "12.30" -> "1230"
        "-0.07" -> "-7"
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    try:
        amount = Decimal(dollars)
    except (InvalidOperation, ValueError):
        raise ValueError("malformed dollar amount") from None

    cents = (amount * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    if cents == 0:
        return "0"

    return str(int(cents))

