def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("missing amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("invalid amount")

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError("invalid dollars component")

    if frac:
        if not frac.isdigit():
            raise ValueError("invalid cents component")
        if len(frac) > 2:
            if any(ch != "0" for ch in frac[2:]):
                raise ValueError("amount has more than two decimal places")
            frac = frac[:2]

    frac = frac.ljust(2, "0")
    digits = (whole + frac).lstrip("0") or "0"
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

