        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    if not s or s[0] in '+-':
        raise ValueError("Invalid amount")

    try:
        d = Decimal(s)
    except InvalidOperation:
        raise ValueError("Invalid amount")

    # Represent in minor units (cents) with half-up rounding.
