import re


_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$")


def _raise_amount_error(message: str) -> None:
    exc_type = ValueError
    try:
        import ledger  # type: ignore

        exc_type = getattr(ledger, "PostError", ValueError)
    except Exception:
        pass

    try:
        exc = exc_type(message)
    except TypeError:
        exc = exc_type()
    raise exc


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _raise_amount_error("amount must be a string")

    text = dollars.strip()
    if not text or not _AMOUNT_RE.fullmatch(text):
        _raise_amount_error("malformed amount")

    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        _raise_amount_error("malformed amount")

    if not value.is_finite():
        _raise_amount_error("malformed amount")

    cents = value * 100
    if cents != cents.to_integral_value():
        _raise_amount_error("too many fractional digits")

    cents_int = int(cents)
    return str(cents_int)

