_CENT = Decimal("0.01")


def encode_amount(dollars: str) -> str:
    try:
        amount = Decimal(dollars.strip())
    except (AttributeError, InvalidOperation):
        raise ValueError("malformed amount")

    if not amount.is_finite():
        raise ValueError("malformed amount")

    cents_amount = amount * 100
    if cents_amount != cents_amount.to_integral_value():
        raise ValueError("malformed amount")

    return str(int(cents_amount))

