def encode_amount(dollars: str) -> str:
    s = dollars.strip().replace("$", "")

    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    elif s.startswith("+"):
        sign = "+"
        s = s[1:]
    else:
        sign = "+"

    if "." in s:
        whole_str, frac_str = s.split(".", 1)
    else:
        whole_str, frac_str = s, ""

    if not whole_str:
        whole_str = "0"

    if len(frac_str) == 0:
        cents = 0
    elif len(frac_str) == 1:
        cents = int(frac_str) * 10
    else:
        cents = int(frac_str[:2])

    total_cents = int(whole_str) * 100 + cents
    digits = str(total_cents)

    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

