from decimal import Decimal, InvalidOperation
import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$")


def _raise_malformed(message: str):
    try:
        import ledger
        exc = ledger.PostError
    except Exception:
        exc = ValueError
    raise exc(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _raise_malformed("amount must be a string")

    text = dollars.strip()
    if not text or not _AMOUNT_RE.fullmatch(text):
        _raise_malformed("malformed amount")

    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError):
        _raise_malformed("malformed amount")

    cents = amount * Decimal("100")
    if cents != cents.to_integral_value():
        _raise_malformed("malformed amount")

    return str(int(cents))

