    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("too many decimal places")

    frac = frac.ljust(2, "0")
    digits = (whole + frac).lstrip("0") or "0"

    sign = "-" if negative and digits != "0" else "+"
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

