def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("missing amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if not whole and not frac:
        raise ValueError("invalid amount")

    if whole and not whole.isdigit():
        raise ValueError("invalid amount")

    if frac and not frac.isdigit():
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("too many decimal places")

    cents_raw = (whole if whole else "0") + frac.ljust(2, "0")
    digits = cents_raw.lstrip("0") or "0"
    check = sum(ord(ch) - ord("0") for ch in digits) % 10

    return f"{sign}{digits}#{check}"

