def encode_amount(dollars: str) -> str:
    s = dollars.strip()

    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    else:
        sign = '+'
        if s.startswith('+'):
            s = s[1:]

    if '.' in s:
        whole, frac = s.split('.', 1)
        if not whole:
            whole = '0'
        # Normalize fractional part to exactly two digits for cents
        frac = (frac + '00')[:2]
        cents = int(whole) * 100 + int(frac)
    else:
        cents = int(s) * 100

    digits = str(abs(cents))
    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"

