import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d{1,2})?|\.\d{1,2})$")


def _post_error(message: str) -> Exception:
    try:
        import ledger
    except Exception:
        return ValueError(message)

    err = getattr(ledger, "PostError", None)
    if err is None:
        return ValueError(message)
    return err(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise _post_error("malformed amount")

    value = dollars.strip()
    if not _AMOUNT_RE.fullmatch(value):
        raise _post_error("malformed amount")

    sign = ""
    if value[0] in "+-":
        sign, value = value[0], value[1:]

    if "." in value:
        whole, frac = value.split(".", 1)
    else:
        whole, frac = value, ""

    if whole == "":
        whole = "0"

    frac = frac.ljust(2, "0")
    cents = int(whole) * 100 + int(frac)

    if cents == 0:
        return "0"

    return f"-{cents}" if sign == "-" else str(cents)

