def encode_amount(dollars: str) -> str:
    # Determine sign and numeric body
    if dollars.startswith("-"):
        sign = "-"
        body = dollars[1:]
    else:
        sign = "+"
        body = dollars[1:] if dollars.startswith("+") else dollars

    # Convert to minor units (cents) as a digit string
    if "." in body:
        whole, frac = body.split(".", 1)
        if not whole:
            whole = "0"
        # Ensure exactly two fractional digits for cents
        if len(frac) == 1:
            frac = frac + "0"
        elif len(frac) > 2:
            frac = frac[:2]
        cents_str = whole + frac
    else:
        if not body:
            body = "0"
        cents_str = body + "00"

    # Canonical form: strip leading zeros, but keep a single zero if value is 0
    digits = cents_str.lstrip("0")
    if not digits:
        digits = "0"

    # Check digit = sum of decimal digits mod 10
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

